/* From Uiverse.io by htwarriors108 - Tags: animation, 3d, loader, cube, rotate, animated, color, hover effect, css effect, rubik's cube */
.__UIV_SCOPE__ .cube {
  width: 100px;
  height: 100px;
  transform-style: preserve-3d;
  animation: animate 4s linear infinite;
  cursor: pointer;
  transition: 0.5s;
}

.__UIV_SCOPE__ .cube:hover {
  scale: 1.2;
  animation: animate 3s linear infinite;
}

.__UIV_SCOPE__ .cube__face {
  position: absolute;
  width: 100px;
  height: 100px;
  display: flex;
  align-items: center;
  flex-direction: row;
  flex-wrap: wrap;
}

.__UIV_SCOPE__ .faceBox {
  border: calc(100px / 1000) solid rgba(0, 0, 0, 0.8);
  width: calc(100px / 3);
  height: calc(100px / 3);
  opacity: 1;
}

.__UIV_SCOPE__ #cube__face--front span {
  background-color: #FF4949;
}

.__UIV_SCOPE__ #cube__face--right span {
  background-color: #13CE66;
}

.__UIV_SCOPE__ #cube__face--left span {
  background-color: #2D8EFF;
}

.__UIV_SCOPE__ #cube__face--top span {
  background-color: #FFCC3D;
}

.__UIV_SCOPE__ #cube__face--bottom span {
  background-color: #fefefe;
}

.__UIV_SCOPE__ #cube__face--back span {
  background-color: #f1f03e;
}

.__UIV_SCOPE__ #cube__face--front {
  transform: rotateY(0deg) translateZ(calc(100px / 2));
}

.__UIV_SCOPE__ #cube__face--right {
  transform: rotateY(90deg) translateZ(calc(100px / 2));
}

.__UIV_SCOPE__ #cube__face--back {
  transform: rotateY(180deg) translateZ(calc(100px / 2));
}

.__UIV_SCOPE__ #cube__face--left {
  transform: rotateY(-90deg) translateZ(calc(100px / 2));
}

.__UIV_SCOPE__ #cube__face--top {
  transform: rotateX(90deg) translateZ(calc(100px / 2));
}

.__UIV_SCOPE__ #cube__face--bottom {
  transform: rotateX(-90deg) translateZ(calc(100px / 2));
}

@keyframes animate {
  0% {
    transform: rotateX(-30deg) rotateY(0deg) rotateZ(0deg);
  }

  100% {
    transform: rotateX(-30deg) rotateY(360deg) rotateZ(360deg);
  }
}
